<?php declare(strict_types=1);
$setupText??=static fn(string $source,array $values=[]):string=>\Kulturhus\Native\Language\ApplicationSetupMessages::text($source,$applicationSetupMessages??[],$values);
$setupEscape=static fn(string $source,array $values=[]):string=>e($setupText($source,$values));
$setupRoute=['view'=>'portal','tab'=>'application','configure'=>'1'];$setupHistoryRoute=$setupRoute+['setup_history'=>'1'];
$setupDraft=$applicationSetupState['draft']??(($applicationSetupRecovery??false)?$_POST:null);$setupOriginal=$applicationSetupState['original']??null;
$setupConfig=$setupDraft!==null?array_intersect_key($setupDraft,array_flip(['fields','payment','notice_title','notice_text','notice_required','enabled'])):($setupOriginal['configuration']??[]);
$setupValue=static fn(string $key):string=>is_string($setupConfig[$key]??null)?$setupConfig[$key]:'';
$setupBoolean=static function(string $key)use($setupDraft,$setupConfig):string{$value=$setupConfig[$key]??null;if($setupDraft===null&&is_bool($value))return$value?'1':'0';return is_string($value)&&in_array($value,['0','1'],true)?$value:'__invalid_original_choice__';};
$setupDisplay=static function(mixed $value,array $labels=[])use($setupText):string{if(is_bool($value))$value=$value?'1':'0';if(is_string($value))return isset($labels[$value])?$setupText($labels[$value]):$value;return json_encode($value,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);};
$setupTime=static fn(string $at):string=>(new DateTimeImmutable($at))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i').' Europe/Berlin';
$setupInvalid=[];foreach(['notice_title'=>'Titel der Hinweise','notice_text'=>'Hinweistext','payment'=>'Zahlungsart','notice_required'=>'Bestätigung der Hinweise','enabled'=>'Öffentlicher Mitgliedsantrag']as$key=>$label)if($setupDraft!==null&&array_key_exists($key,$setupDraft)&&!is_string($setupDraft[$key]))$setupInvalid[$setupText($label)]=$setupDraft[$key];
if($setupDraft!==null&&isset($setupDraft['fields'])){if(!is_array($setupDraft['fields']))$setupInvalid[$setupText('Persönliche Daten')]=$setupDraft['fields'];else foreach($setupDraft['fields']as$key=>$value)if(!is_string($value)||!in_array($value,['hidden','optional','required'],true))$setupInvalid[$setupText(\Kulturhus\Verein\MembershipApplications::FIELDS[$key]??'Unbekannte Antragsfelder.')]=$value;}
$setupHistoryList=static function(array $history,bool $separate)use($setupEscape,$setupTime,$setupHistoryRoute):void{ ?>
<section class="setup-history" data-application-setup-history><h3><?= $setupEscape('Änderungsverlauf') ?></h3>
<?php if(!$history['rows']): ?><p><?= $setupEscape('Noch keine Änderungen gespeichert.') ?></p><?php else: ?><ol class="setup-history-list"><?php foreach($history['rows']as$row): ?><li><a class="btn btn-outline theme-secondary" <?= $separate?'':'target="_blank" rel="noopener"' ?> href="<?= e(url($setupHistoryRoute+['setup_revision'=>$row['version'],'setup_page'=>$history['page']])) ?>"><?= $setupEscape('Änderung vom {time}',['time'=>$setupTime($row['happened_at'])]) ?></a></li><?php endforeach ?></ol><?php endif ?>
<?php if($separate): ?><nav class="setup-actions" aria-label="<?= $setupEscape('Verlaufsseiten') ?>"><span><?= $setupEscape('Seite {page} von {pages} · {count} Änderungen',['page'=>$history['page'],'pages'=>$history['pages'],'count'=>$history['total']]) ?></span><?php foreach([-1=>'Vorherige Seite',1=>'Nächste Seite']as$delta=>$label):$page=$history['page']+$delta;if($page<1||$page>$history['pages'])continue; ?><a class="btn btn-outline theme-secondary" href="<?= e(url($setupHistoryRoute+['setup_page'=>$page])) ?>"><?= $setupEscape($label) ?></a><?php endforeach ?></nav><?php else: ?><a class="btn btn-outline theme-secondary" target="_blank" rel="noopener" href="<?= e(url($setupHistoryRoute)) ?>"><?= $setupEscape('Gesamten Verlauf öffnen') ?></a><?php endif ?></section>
<?php }; ?>
<link rel="stylesheet" href="application-setup.css?v=1">
<div class="content" data-application-setup>
<h2 data-application-setup-heading><?= $setupEscape('Mitgliedsantrag einrichten') ?></h2>
<?php if($applicationSetupError!==''): ?><section class="card" role="alert"><p><?= e($applicationSetupError) ?></p></section><?php endif ?>
<?php if($applicationSetupRecovery): ?><section class="card"><h3><?= $setupEscape('Angaben') ?></h3><p><?= $setupEscape('Der Speicherstand ist noch nicht bestätigt. Prüfe dieselben Angaben erneut, sobald der Bereich wieder verfügbar ist.') ?></p><dl class="data-list"><?php foreach(['notice_title'=>'Titel der Hinweise','notice_text'=>'Hinweistext','payment'=>'Zahlungsart','notice_required'=>'Bestätigung der Hinweise','enabled'=>'Öffentlicher Mitgliedsantrag']as$key=>$label):if(!array_key_exists($key,$_POST))continue; ?><dt><?= $setupEscape($label) ?></dt><dd><?= nl2br(e($setupDisplay($_POST[$key],match($key){'payment'=>['invoice'=>'Rechnung'],'notice_required'=>['0'=>'Hinweise nur anzeigen','1'=>'Bestätigung erforderlich'],'enabled'=>['0'=>'Nicht aktiv','1'=>'Aktiv'],default=>[]}))) ?></dd><?php endforeach ?><?php foreach(is_array($_POST['fields']??null)?$_POST['fields']:[]as$key=>$value): ?><dt><?= $setupEscape(\Kulturhus\Verein\MembershipApplications::FIELDS[$key]??'Unbekannte Antragsfelder.') ?></dt><dd><?= e($setupDisplay($value,['hidden'=>'Nicht abfragen','optional'=>'Freiwillige Angabe','required'=>'Pflichtfeld'])) ?></dd><?php endforeach ?></dl><form method="post" action="<?= e(url($setupRoute)) ?>" data-application-setup-recovery><?= csrf().\Kulturhus\Verein\Web\ApplicationSetupForm::recoveryHidden($_POST).hidden('application_setup_recheck','1') ?><button class="btn btn-solid theme-primary" data-application-setup-recheck><?= $setupEscape('Angaben erneut prüfen') ?></button></form></section><?php endif ?>
<?php if(!$applicationSetupAllowed): ?><p><?= $setupEscape('Antragseinrichtung nicht verfügbar.') ?></p><a class="btn btn-outline theme-secondary" href="<?= e(url($setupRoute)) ?>"><?= $setupEscape('Aktuelle Einrichtung bewusst öffnen') ?></a></div><?php return;endif ?>
<?php if($applicationSetupHistoryMode): ?>
<p><a class="btn btn-outline theme-secondary" href="<?= e(url($setupRoute)) ?>"><?= $setupEscape('Zu den aktuellen Einstellungen') ?></a></p>
<?php if($applicationSetupHistory['selected']!==null):$selected=$applicationSetupHistory['selected']; ?><section class="card" data-application-setup-original><h3><?= $setupEscape('Gespeicherte Einstellungen') ?></h3><p><?= e($setupTime($selected['happened_at'])) ?></p>
<?php foreach(['before'=>'Vor dieser Änderung','after'=>'Nach dieser Änderung']as$which=>$label):$source=$selected['original'][$which];$row=$selected['original'][$which.'_row']; ?><details class="setup-original" <?= $which==='after'?'open':'' ?>><summary><?= $setupEscape($label) ?></summary><?php if($row===null): ?><p><?= $setupEscape('Noch keine gespeicherte Einrichtung vorhanden.') ?></p><?php else:$raw=json_decode($row['configuration'],true,64,JSON_THROW_ON_ERROR); ?><h4><?= $setupEscape('Gespeicherte Originalhinweise') ?></h4><h5><?= e($raw['notice_title']) ?></h5><p class="setup-original-text"><?= e($raw['notice_text']) ?></p><?php if($raw['notice_text']!==$source['configuration']['notice_text']): ?><h4><?= $setupEscape('Bisher im Antrag angezeigte Hinweise') ?></h4><p class="setup-original-text"><?= e($source['configuration']['notice_text']) ?></p><?php endif ?><?php foreach(['single'=>'Einzelmitglied: {amount} jährlich','family'=>'Familie: {amount} jährlich insgesamt']as$type=>$caption): ?><p><?= $setupEscape($caption,['amount'=>\Kulturhus\Verein\ContributionRates::label($source['rates'][$type]['amount_cents'])]) ?></p><?php endforeach ?><dl class="data-list"><?php foreach(['payment'=>'Zahlungsart','notice_required'=>'Bestätigung der Hinweise','enabled'=>'Öffentlicher Mitgliedsantrag']as$key=>$caption): ?><dt><?= $setupEscape($caption) ?></dt><dd><?= e($setupDisplay($source['configuration'][$key],match($key){'payment'=>['invoice'=>'Rechnung'],'notice_required'=>['0'=>'Hinweise nur anzeigen','1'=>'Bestätigung erforderlich'],'enabled'=>['0'=>'Nicht aktiv','1'=>'Aktiv']})) ?></dd><?php endforeach ?><?php foreach(\Kulturhus\Verein\MembershipApplications::FIELDS as$key=>$caption): ?><dt><?= $setupEscape($caption) ?></dt><dd><?= $setupEscape(['hidden'=>'Nicht abfragen','optional'=>'Freiwillige Angabe','required'=>'Pflichtfeld'][$source['configuration']['fields'][$key]]) ?></dd><?php endforeach ?></dl><?php endif ?></details><?php endforeach ?></section><?php endif ?>
<?php $setupHistoryList($applicationSetupHistory,true); ?></div><?php return;endif ?>
<?php if($applicationSetupState['saved_version']!==null): ?><section class="card" role="status"><h3><?= $setupEscape('Einrichtung bereits gespeichert') ?></h3><p><?= $setupEscape('Diese Änderung wurde bereits gespeichert. Erneut gesendete Angaben wurden nicht übernommen.') ?></p><a class="btn btn-solid theme-primary" data-application-setup-saved href="<?= e(url($setupHistoryRoute+['setup_revision'=>$applicationSetupState['saved_version']])) ?>"><?= $setupEscape('Gespeicherte Einstellungen öffnen') ?></a></section><?php endif ?>
<?php if($applicationSetupState['stale']): ?><section class="card" role="alert"><p><?= $setupEscape('Die ursprüngliche Einrichtung oder die angezeigten Beiträge wurden geändert. Deine Angaben bleiben erhalten. Öffne die aktuelle Einrichtung und prüfe sie vor einer neuen Speicherung.') ?></p><a class="btn btn-outline theme-secondary" data-application-setup-current href="<?= e(url($setupRoute)) ?>"><?= $setupEscape('Aktuelle Einrichtung bewusst öffnen') ?></a></section><?php endif ?>
<?php if($setupInvalid): ?><details class="card" open><summary><?= $setupEscape('Fehlerhafte Auswahl') ?></summary><pre><?= e(json_encode($setupInvalid,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE)) ?></pre></details><?php endif ?>
<form method="post" action="<?= e(url($setupRoute)) ?>" class="card application-config" data-application-setup-form data-application-setup-wizard data-setup-step="<?= $applicationSetupStep ?>"><?= csrf().hidden('action','save-application-settings').hidden('application_setup_intent','save').hidden('version',$applicationSetupState['version']).hidden('application_setup_source',$applicationSetupState['source']).hidden('application_setup_fingerprint',$applicationSetupState['fingerprint']).hidden('request_key',$applicationSetupState['request_key']) ?>
<nav class="setup-progress" aria-label="<?= $setupEscape('Mitgliedsantrag einrichten') ?>" hidden data-setup-enhanced><?php foreach(['1 · Persönliche Daten','2 · Beitragsrechnung','3 · Hinweise & Aktivierung']as$step=>$label): ?><button class="btn btn-outline theme-secondary" type="button" data-setup-go="<?= $step ?>"><?= $setupEscape($label) ?></button><?php endforeach ?></nav>
<section data-setup-step="0"><h3 tabindex="-1"><?= $setupEscape('Welche persönlichen Daten möchtest du abfragen?') ?></h3><p><?= $setupEscape('Vorname, Nachname, Geburtsdatum und E-Mail bleiben Pflichtfelder. Den Kommunikationsweg fragt dieser Antrag nicht ab. Alle anderen Felder kannst du wählen.') ?></p><div class="setup-field-grid"><?php foreach(\Kulturhus\Verein\MembershipApplications::FIELDS as$key=>$label):$mode=is_array($setupConfig['fields']??null)&&is_string($setupConfig['fields'][$key]??null)?$setupConfig['fields'][$key]:''; ?><fieldset><legend><?= $setupEscape($label) ?></legend><?php foreach(['hidden'=>'Nicht abfragen','optional'=>'Freiwillige Angabe','required'=>'Pflichtfeld']as$value=>$caption):$fixed=(in_array($key,['first_name','last_name','birthday','email'],true)&&$value!=='required')||($key==='communication_channel'&&$value!=='hidden'); ?><label class="setup-choice"><input type="radio" name="fields[<?= e($key) ?>]" value="<?= $value ?>" <?= $mode===$value?'checked':'' ?> <?= $fixed?'disabled':'required' ?>><?= $setupEscape($caption) ?></label><?php endforeach ?></fieldset><?php endforeach ?></div><button class="btn btn-solid theme-primary" type="button" data-setup-next data-setup-enhanced hidden><?= $setupEscape('Zur Beitragsrechnung') ?></button></section>
<section data-setup-step="1"><h3 tabindex="-1"><?= $setupEscape('Rechnung nach bestätigter Aufnahme') ?></h3><label><?= $setupEscape('Zahlungsart') ?><select name="payment" class="form-control" required><?php if($setupValue('payment')!=='invoice'): ?><option value="__invalid_original_choice__" selected><?= $setupEscape('Fehlerhafte Auswahl') ?></option><?php endif ?><option value="invoice" <?= $setupValue('payment')==='invoice'?'selected':'' ?>><?= $setupEscape('Rechnung') ?></option></select></label><?php if($setupOriginal!==null):foreach(['single'=>'Einzelmitglied: {amount} jährlich','family'=>'Familie: {amount} jährlich insgesamt']as$type=>$caption): ?><p><?= $setupEscape($caption,['amount'=>\Kulturhus\Verein\ContributionRates::label($setupOriginal['rates'][$type]['amount_cents'])]) ?></p><?php endforeach;endif ?><p><?= $setupEscape('Nach bestätigter Aufnahme erhält das zahlende Mitglied eine Beitragsrechnung. Familienangehörige erhalten keine eigene Rechnung. Das Zahlungsziel beträgt einen Monat ab Rechnungsdatum.') ?></p><p><?= $setupEscape('Mit {{EINZELBEITRAG}} und {{FAMILIENBEITRAG}} kannst du die geltenden Jahresbeiträge in deine Hinweise einsetzen.') ?></p><div class="setup-actions"><button class="btn btn-outline theme-secondary" type="button" data-setup-back data-setup-enhanced hidden><?= $setupEscape('Zurück') ?></button><button class="btn btn-solid theme-primary" type="button" data-setup-next data-setup-enhanced hidden><?= $setupEscape('Zu den Hinweisen') ?></button></div></section>
<section data-setup-step="2"><h3 tabindex="-1"><?= $setupEscape('Eigene Hinweise für den Antrag') ?></h3><p><?= $setupEscape('Die Beitragsplatzhalter werden im Antrag durch den geltenden Beitrag ersetzt.') ?></p><label><?= $setupEscape('Titel der Hinweise') ?><input class="form-control" name="notice_title" required maxlength="150" value="<?= e($setupValue('notice_title')) ?>"></label><label><?= $setupEscape('Hinweistext') ?><textarea class="form-control" name="notice_text" required maxlength="10000" rows="8"><?= e($setupValue('notice_text')) ?></textarea></label>
<?php foreach(['notice_required'=>['Bestätigung der Hinweise','Hinweise nur anzeigen','Bestätigung erforderlich'],'enabled'=>['Öffentlicher Mitgliedsantrag','Nicht aktiv','Aktiv']]as$key=>[$label,$no,$yes]):$value=$setupBoolean($key); ?><label><?= $setupEscape($label) ?><select name="<?= $key ?>" class="form-control" required><?php if(!in_array($value,['0','1'],true)): ?><option value="__invalid_original_choice__" selected><?= $setupEscape('Fehlerhafte Auswahl') ?></option><?php endif ?><option value="0" <?= $value==='0'?'selected':'' ?>><?= $setupEscape($no) ?></option><option value="1" <?= $value==='1'?'selected':'' ?>><?= $setupEscape($yes) ?></option></select></label><?php endforeach ?>
<p><?= $setupEscape('Bestätigung per E-Mail und Vorstandsentscheidung bleiben erforderlich. Diese Einstellung versendet selbst keine Nachricht.') ?></p><div class="setup-actions"><button class="btn btn-outline theme-secondary" type="button" data-setup-back data-setup-enhanced hidden><?= $setupEscape('Zurück') ?></button><button class="btn btn-solid theme-primary" data-application-setup-save <?= $applicationSetupState['stale']||$applicationSetupState['saved_version']!==null?'disabled':'' ?>><?= $setupEscape('Einrichtung speichern') ?></button></div></section></form>
<?php if($applicationSetupHistory!==null): ?><details class="card"><summary><?= $setupEscape('Änderungsverlauf') ?></summary><?php $setupHistoryList($applicationSetupHistory,false); ?></details><?php endif ?>
</div><script src="application-setup.js?v=1" defer></script>
